import {handleIndependent} from './writing-independent.ts';
import { handleLive } from './live.ts';
import { handleProfileName } from './profile-name.ts';
import { handleLegacy } from './organization.ts';
import { handle as handleImport } from './import-assistant.ts';
import { handleGoogle } from './google-signup.ts';
const actions=new Set(['import_status','import_review','import_commit','import_organize']);
export async function route(req:Request,deps={legacy:handleLegacy,assisted:handleImport,google:handleGoogle,profileName:handleProfileName,live:handleLive,independent:handleIndependent}){
 if(req.method==='POST'){
  if(req.headers.get('Content-Type')?.startsWith('multipart/form-data')){const form=await req.clone().formData();if(form.get('action')==='live_upload')return deps.live(req);}
  let body:any;
  try{const raw=await req.clone().text();if(raw.length<=250000)body=JSON.parse(raw);}catch{}
  if(typeof body?.action==='string'&&['live_manage','live_activities','live_activity','writing_guidance','writing_catalog','writing_activities','writing_activity_save','writing_activity_get','writing_join','writing_detail','writing_revision','writing_comment','live_writing_list','live_writing_get','live_writing_save','live_transcribe','live_confirm_text','live_status','live_create','live_theme','live_start','live_get','live_history','live_review','live_share','live_shares','live_revoke'].includes(body.action))return deps.live(req);
  if(body?.action==='student_complete')return deps.independent(req);
  if(body?.action==='update_name')return deps.profileName(req);
  if(body?.action==='google_complete')return deps.google(req);
  if(body&&actions.has(body.action)){
   return deps.assisted(new Request(req.url,{method:'POST',headers:req.headers,body:JSON.stringify({...body,action:body.action.slice(7)})}));
  }
 }
 return deps.legacy(req);
}
Deno.serve((req:Request)=>route(req));

import {createClient} from 'npm:@supabase/supabase-js@2.57.4';
const headers={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,content-type,x-client-info','Access-Control-Allow-Methods':'POST,OPTIONS','Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
export async function handleIndependent(req:Request,deps={createClient,env:(k:string)=>Deno.env.get(k)}){
 const reply=(body:unknown,status=200)=>new Response(JSON.stringify(body),{status,headers});
 if(req.method==='OPTIONS')return reply({});if(req.method!=='POST')return reply({error:'Método não permitido.'},405);
 try{
  const auth=req.headers.get('Authorization')||'';if(!auth.startsWith('Bearer '))return reply({error:'Entre novamente.'},401);
  const admin=deps.createClient(deps.env('SUPABASE_URL')!,deps.env('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
  const identity=await admin.auth.getUser(auth.slice(7));if(identity.error||!identity.data.user)return reply({error:'Sessão inválida.'},401);
  const raw=await req.text();if(raw.length>3000)return reply({error:'Dados inválidos.'},413);const body=JSON.parse(raw);
  if(body.action!=='student_complete'||body.accept_terms!==true||body.legal_version!=='2026-09-28'||typeof body.full_name!=='string'||body.full_name.trim().length<2||body.full_name.length>160)return reply({error:'Confira seu nome e aceite os termos.'},400);
  const r=await admin.rpc('complete_independent_student',{p_actor:identity.data.user.id,p_name:body.full_name,p_accept:true,p_legal_version:body.legal_version});
  if(r.error)return reply({error:['42501','P0001'].includes(r.error.code)?r.error.message:'Não foi possível concluir o cadastro.'},400);
  return reply(r.data);
 }catch{return reply({error:'Não foi possível concluir o cadastro. Tente novamente.'},503);}
}

import {guideWriting} from './writing-tutor.ts';
import {transcribeLive} from './live-transcription.ts';
import {partial} from './partial.ts';
import {listSearch,essaySummaries,activitySummaries} from './live-list.ts';
import {meteredFetch} from './ai-metering.ts';
import {verifyLiveInput} from './live-input.ts';
import {validateLiveFile} from './live-files.ts';
import {createClient} from 'npm:@supabase/supabase-js@2.57.4';
import {ESSENTIAL_PROTOCOL} from './protocolo-essencial.ts';
import {QUALITY_INSTRUCTIONS,consultedSources,reviewedEvidence,validateEvidence,inputManifest} from './correction-quality.ts';
import {schema,normalizeResult,extractOutputText} from './live-ai.ts';
const headers={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,content-type,x-client-info','Access-Control-Allow-Methods':'POST,OPTIONS','Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store'};
const json=(data:unknown,status=200)=>new Response(JSON.stringify(data),{status,headers});
const uuid=(value:unknown)=>typeof value==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
const clean=(value:unknown,max:number)=>String(value??'').normalize('NFC').trim().replace(/[\t ]+/g,' ').slice(0,max);
const contextKey=(value:Record<string,string>)=>JSON.stringify(Object.entries(value).sort(([a],[b])=>a.localeCompare(b)));
function checked(result:any){if(result.error)throw result.error;return result.data;}
function visible(job:any){if(!job)return null;return {id:job.id,essay_id:job.essay_id,purpose:job.purpose,correction_scope:job.correction_scope||'complete',status:job.status,credit_status:job.credit_status,result:job.result,review:job.review,reviewed_at:job.reviewed_at,error_message:job.error_message,theme:job.theme_snapshot,theme_origin:job.theme_origin,created_at:job.created_at,completed_at:job.completed_at};}
export async function handleLive(req:Request,deps={createClient,fetch,env:(key:string)=>Deno.env.get(key)}){
 if(req.method==='OPTIONS')return new Response('ok',{headers});
 if(req.method!=='POST')return json({error:'Método não permitido.'},405);
 try{
  const auth=req.headers.get('Authorization')||'';if(!auth.startsWith('Bearer '))return json({error:'Entre novamente.'},401);
  const admin=deps.createClient(deps.env('SUPABASE_URL')!,deps.env('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
  const identity=await admin.auth.getUser(auth.slice(7));if(identity.error||!identity.data.user)return json({error:'Sessão inválida.'},401);
  const actor=identity.data.user.id;
  const profile=checked(await admin.from('profiles').select('id,role,approval_status,admin_hidden,organization_id').eq('id',actor).maybeSingle());
  if(!['teacher','student'].includes(profile?.role)||profile.approval_status!=='approved'||profile.admin_hidden)return json({error:'Sem acesso ao Ao Vivo.'},403);
  if(profile.role==='student'){
   const student=checked(await admin.from('students').select('auth_user_id,organization_id').eq('auth_user_id',actor).maybeSingle());
   const independent=!profile.organization_id&&checked(await admin.from('system_feature_flags').select('is_enabled').eq('feature_key','student_independent').maybeSingle())?.is_enabled===true&&!!checked(await admin.from('student_independent_accounts').select('profile_id').eq('profile_id',actor).maybeSingle());
   if(!independent&&(!student||student.auth_user_id!==actor||!profile.organization_id||student.organization_id!==profile.organization_id))return json({error:'Disponível neste momento para alunos da base. Entre pelo acesso da sua turma.'},403);
  }
  let body:any,upload:File|null=null;
  if(req.headers.get('Content-Type')?.startsWith('multipart/form-data')){
   if(Number(req.headers.get('Content-Length')||0)>16000000)return json({error:'Arquivo muito grande.'},413);
   const form=await req.formData();body=Object.fromEntries(form.entries());upload=form.get('file') as File;
   if(body.action!=='live_upload'||!(upload instanceof File))return json({error:'Arquivo inválido.'},400);
  }else{
   const raw=await req.text();if(raw.length>100000)return json({error:'Dados muito grandes.'},413);
   try{body=JSON.parse(raw);}catch{return json({error:'Dados inválidos.'},400);}
  }
  const flag=checked(await admin.from('system_feature_flags').select('is_enabled,config').eq('feature_key',profile.role==='student'?'student_live':'teacher_live').maybeSingle());
  const partialFlag=checked(await admin.from('system_feature_flags').select('is_enabled,config').eq('feature_key','live_partial_correction').maybeSingle());
  const partialEnabled=partialFlag?.is_enabled===true;
  const wallet=checked(await admin.from('correction_credit_wallets').select('balance').eq('profile_id',actor).maybeSingle());
  if(body.action==='live_status'){
   const balance=profile.role==='student'&&flag?.is_enabled?checked(await admin.rpc('claim_student_trial',{p_actor:actor})):wallet?.balance||0;
   return json({enabled:!!flag?.is_enabled,balance,correction_credits:1,independent:profile.role==='student'&&!profile.organization_id,management:true,partial_correction:partialEnabled,partial_input:partialFlag?.config?.camera===true?'text-or-file':'text',writing_editor:partialFlag?.config?.writing_editor===true,writing_guided:checked(await admin.from('system_feature_flags').select('is_enabled,config').eq('feature_key','writing_guided').maybeSingle())});
  }
  if(!flag?.is_enabled)return json({error:'O Ao Vivo ainda não está disponível.'},409);
  async function ownEssay(id:string){if(!uuid(id))throw Error('Redação inválida.');const essay=checked(await admin.from('live_essays').select('*').eq('id',id).eq('owner_id',actor).maybeSingle());if(!essay||essay.deleted_at)throw Error('Redação não encontrada.');return essay;}
  async function finish(job:any,provider:any,error:string|null=null){
   let result=null;
   if(!error){
    try{
     const parsed=JSON.parse(extractOutputText(provider));
     if(job.purpose==='theme'){
      if(typeof parsed.theme!=='string'||parsed.theme.trim().length<10||parsed.theme.length>(job.correction_scope&&job.correction_scope!=='complete'?1000:4000))throw Error('Tema inválido.');
      result={theme:parsed.theme,requires_confirmation:true};
     }else if(job.correction_scope&&job.correction_scope!=='complete'){
      result={...partial.normalize(parsed,{stage:job.correction_scope,theme:job.theme_snapshot,text:job.input_snapshot,context:job.context_snapshot||{}}),audience:profile.role,reviewed_by_teacher:false};
     }else{
      result={...normalizeResult(parsed,consultedSources(provider)),request_manifest:job.result?.request_manifest||null,audience:profile.role,reviewed_by_teacher:false,delivery_label:profile.role==='student'?'Estimativa por IA · sem revisão de professor':'Análise para revisão do professor'};
      if(job.theme_origin==='inferred')result={...result,proposal_complete:false,needs_manual_review:true,c2_context:'Recorte inferido e confirmado; não comprova atendimento à proposta original.'};
     }
    }catch{error='Não foi possível concluir uma análise válida. O crédito desta tentativa será devolvido.';}
   }
   return checked(await admin.rpc('finish_live_job',{p_actor:actor,p_job:job.id,p_result:result,p_usage:provider?.usage||null,p_error:error}));
  }
  const key=deps.env('OPENAI_API_KEY');
  async function reconcile(job:any){
   if(job.status!=='processing')return job;
   const age=Date.now()-Date.parse(job.created_at);
   if(age>600000)return finish(job,null,'A análise excedeu o tempo disponível. O crédito desta tentativa será devolvido.');
   if(!job.provider_id||!key)return job;
   const response=await meteredFetch(admin,{table:'live_jobs',id:job.id,actor,service:'Ao Vivo',stage:job.purpose},'https://api.openai.com/v1/responses/'+encodeURIComponent(job.provider_id)+'?include[]=web_search_call.action.sources',{headers:{Authorization:'Bearer '+key},signal:AbortSignal.timeout(10000)},deps.fetch);
   if(response.status===404)return finish(job,null,'A análise não está mais disponível. O crédito desta tentativa será devolvido.');
   if(!response.ok)return job;
   const provider=await response.json();
   if(provider.status==='completed')return finish(job,provider);
   if(['failed','cancelled','incomplete'].includes(provider.status))return finish(job,provider,'A análise não foi concluída. O crédito desta tentativa será devolvido.');
   return job;
  }
  if(['writing_guidance','writing_catalog','writing_activity_save','writing_join','writing_comment'].includes(body.action)&&checked(await admin.from('system_feature_flags').select('is_enabled').eq('feature_key','writing_guided').maybeSingle())?.is_enabled!==true)return json({error:'A construção guiada ainda não está liberada.'},409);
  if(body.action==='writing_guidance')return json(await guideWriting({admin,actor,body,key,fetcher:deps.fetch}));
  if(['writing_catalog','writing_activities','writing_activity_save','writing_activity_get','writing_join','writing_detail','writing_revision','writing_comment'].includes(body.action))return json(checked(await admin.rpc('writing_dispatch',{p_actor:actor,p_body:body})));
  if(body.action==='live_writing_list')return json({drafts:checked(await admin.from('live_writing_drafts').select('id,theme,version,updated_at').eq('owner_id',actor).order('updated_at',{ascending:false}).limit(50))});
  if(['live_writing_get','live_writing_save'].includes(body.action)){
   if(!uuid(body.id))return json({error:'Rascunho inválido.'},400);
   if(body.action==='live_writing_get'){
    const draft=checked(await admin.from('live_writing_drafts').select('*').eq('id',body.id).eq('owner_id',actor).maybeSingle());
    return draft?json(checked(await admin.rpc('writing_access',{p_actor:actor,p_draft:body.id}))):json({error:'Rascunho não encontrado.'},404);
   }
   if(partialFlag?.config?.writing_editor!==true)return json({error:'O editor está temporariamente indisponível para salvar.'},409);
   if(!Number.isInteger(body.version)||body.version<0||typeof body.theme!=='string'||body.theme.length>1000||!body.content||typeof body.content!=='object'||Array.isArray(body.content))return json({error:'Rascunho inválido.'},400);
   if(body.content.command!==undefined&&(typeof body.content.command!=='string'||body.content.command.length>4000))return json({error:'Confira o comando do tema.'},400);
   const content:any={mode:body.content.mode==='cause-effect'?'cause-effect':'free',command:body.content.command||'',stages:{}};
   for(const stage of ['introduction','development1','development2','conclusion']){
    const data=body.content.stages?.[stage]||{};
    if(typeof data.text!=='string'||data.text.length>16000||typeof data.plan!=='string'||data.plan.length>4000)return json({error:'Confira o texto e o planejamento de cada etapa.'},400);
    content.stages[stage]={text:data.text,plan:data.plan};
   }
   return json({draft:checked(await admin.rpc('save_live_writing_draft',{p_actor:actor,p_id:body.id,p_version:body.version,p_theme:body.theme,p_content:content}))});
  }
  if(body.action==='live_upload'){
   const correction_scope=partial.scope(body.correction_scope);
   if(correction_scope!=='complete'&&(!partialEnabled||partialFlag?.config?.camera!==true))return json({error:'Câmera para correção parcial indisponível.'},409);
   if(!uuid(body.essay_id)||!upload)return json({error:'Arquivo inválido.'},400);
   if(upload.size>15728640)return json({error:'Use um arquivo de até 15 MB.'},413);
   const bytes=new Uint8Array(await upload.arrayBuffer()),mime=validateLiveFile(upload.name,bytes);
   let essay=checked(await admin.from('live_essays').select('*').eq('id',body.essay_id).eq('owner_id',actor).maybeSingle());
   if(essay){
    if((essay.correction_scope||'complete')!==correction_scope)return json({error:'Comece uma nova redação para trocar a etapa.'},409);
    if(essay.deleted_at)return json({error:'Redação excluída. Comece uma nova redação.'},409);
    const current=checked(await admin.from('live_files').select('original_name').eq('essay_id',essay.id).maybeSingle());
    if(current)return json({essay,reused:true});
    if(essay.input_text)return json({error:'Comece uma nova redação para trocar o texto por arquivo.'},409);
   }else essay=checked(await admin.from('live_essays').insert({id:body.essay_id,owner_id:actor,correction_scope,student_label:clean(body.student_label,160),school_label:clean(body.school_label,160)}).select('*').single());
   const path=actor+'/'+essay.id+'/'+crypto.randomUUID()+'.'+upload.name.split('.').pop()?.toLowerCase();
   checked(await admin.storage.from('live-private').upload(path,bytes,{contentType:mime,upsert:false}));
   try{checked(await admin.from('live_files').insert({essay_id:essay.id,storage_path:path,original_name:clean(upload.name,240),mime_type:mime,file_size:bytes.length}));}
   catch(error){await admin.storage.from('live-private').remove([path]);throw error;}
   return json({essay});
  }
  if(body.action==='live_create'){
   const correction_scope=partial.scope(body.correction_scope);
   const writing_context:any={};if(body.writing_context!==undefined){if(!body.writing_context||typeof body.writing_context!=='object'||Array.isArray(body.writing_context))return json({error:'Contexto inválido.'},400);for(const [k,v] of Object.entries(body.writing_context)){if(!['introduction','development1','development2','conclusion'].includes(k)||k===correction_scope||typeof v!=='string'||v.length>16000)return json({error:'Contexto inválido.'},400);writing_context[k]=v;}}
   if(correction_scope!=='complete'&&!partialEnabled)return json({error:'Correção parcial ainda não habilitada.'},409);
   if(correction_scope!=='complete'&&typeof body.input_text==='string'&&body.input_text.length>16000)return json({error:'Use até 16.000 caracteres no trecho.'},400);
   if(!uuid(body.essay_id))return json({error:'Identificador inválido.'},400);
   if(typeof body.input_text!=='string'||body.input_text.trim().length<80||body.input_text.length>20000)return json({error:'Use entre 80 e 20.000 caracteres.'},400);
   const prior=checked(await admin.from('live_essays').select('*').eq('id',body.essay_id).eq('owner_id',actor).maybeSingle());
   if(prior?.deleted_at)return json({error:'Redação excluída. Comece uma nova redação.'},409);
   if(prior){if((prior.correction_scope||'complete')!==correction_scope||prior.input_text!==body.input_text||contextKey(prior.writing_context||{})!==contextKey(writing_context))return json({error:'Identificador já utilizado por outro conteúdo.'},409);return json({essay:prior,reused:true});}
   const essay=checked(await admin.from('live_essays').insert({id:body.essay_id,owner_id:actor,input_text:body.input_text,correction_scope,writing_context,student_label:clean(body.student_label,160),school_label:clean(body.school_label,160)}).select('*').single());
   return json({essay});
  }
  if(body.action==='live_manage'){
   if(!uuid(body.id)||!['essay','activity'].includes(body.kind)||!['edit','delete'].includes(body.operation))return json({error:'Operação inválida.'},400);
   if(body.kind==='activity'&&profile.role!=='teacher')return json({error:'Atividades disponíveis somente para professor.'},403);
   return json(checked(await admin.rpc('manage_live_item',{p_actor:actor,p_kind:body.kind,p_id:body.id,p_operation:body.operation,p_name:clean(body.name,160),p_school:clean(body.school,160)})));
  }
  if(body.action==='live_activities'){
   if(profile.role!=='teacher')return json({error:'Atividades disponíveis somente para professor.'},403);
   const offset=Math.max(0,Math.min(10000,Number(body.offset)||0));
   let query=admin.from('live_activities').select('*').eq('owner_id',actor);
   if(body.activity_id){if(!uuid(body.activity_id))return json({error:'Atividade inválida.'},400);query=query.eq('id',body.activity_id);}else query=query.is('deleted_at',null);
   const search=listSearch(body.search);if(search)query=query.or('name.ilike.%'+search+'%,theme.ilike.%'+search+'%');
   const rows=checked(await query.order('created_at',{ascending:false}).order('id').range(offset,offset+20));
   const activities=body.include_summary?await activitySummaries(admin,actor,rows.slice(0,20)):rows.slice(0,20);
   return json({activities,has_more:rows.length>20});
  }
  if(body.action==='live_history'){
   const offset=Math.max(0,Math.min(10000,Number(body.offset)||0));
   let query=admin.from('live_essays').select('id,student_label,school_label,theme,created_at,activity_id,correction_scope').eq('owner_id',actor).is('deleted_at',null);
   if(body.activity_id){if(profile.role!=='teacher')return json({error:'Atividades disponíveis somente para professor.'},403);if(!uuid(body.activity_id))return json({error:'Atividade inválida.'},400);query=query.eq('activity_id',body.activity_id);}
   const search=listSearch(body.search);if(search)query=query.or('student_label.ilike.%'+search+'%,school_label.ilike.%'+search+'%,theme.ilike.%'+search+'%');
   const rows=checked(await query.order('created_at',{ascending:false}).order('id').range(offset,offset+20));
   const essays=body.include_summary?await essaySummaries(admin,actor,rows.slice(0,20)):rows.slice(0,20);
   return json({essays,has_more:rows.length>20});
  }
  if(body.action==='live_activity'){
   if(profile.role!=='teacher')return json({error:'Atividades disponíveis somente para professor.'},403);
   if(body.confirmed!==true||!uuid(body.activity_id)||!uuid(body.essay_id))return json({error:'Confirme o tema da atividade.'},400);
   return json(checked(await admin.rpc('attach_live_activity',{p_actor:actor,p_essay:body.essay_id,p_activity:body.activity_id,p_name:clean(body.name,160),p_theme:body.theme,p_origin:body.theme_origin})));
  }
  const essay=await ownEssay(body.essay_id);
  if(['live_transcribe','live_confirm_text'].includes(body.action)){
   if(!partialEnabled||!essay.correction_scope||essay.correction_scope==='complete')return json({error:'Leitura por etapa indisponível.'},409);
   if(body.action==='live_transcribe')return json(await transcribeLive({admin,actor,essay,key,fetcher:deps.fetch}));
   if(body.confirmed!==true||typeof body.input_text!=='string'||body.input_text.trim().length<80||body.input_text.length>16000)return json({error:'Confira o trecho, entre 80 e 16.000 caracteres.'},400);
   return json({essay:checked(await admin.rpc('confirm_live_transcription',{p_actor:actor,p_essay:essay.id,p_text:body.input_text}))});
  }
  if(['live_review','live_share','live_shares','live_revoke'].includes(body.action)){
   if(!uuid(body.job_id))return json({error:'Correção inválida.'},400);
   const job=checked(await admin.from('live_jobs').select('*').eq('id',body.job_id).eq('essay_id',essay.id).eq('owner_id',actor).maybeSingle());
   if(!job||job.status!=='completed'||job.purpose!=='correction')return json({error:'Correção concluída não encontrada.'},404);
   if(body.action==='live_review'){
    if(profile.role!=='teacher')return json({error:'A revisão docente é exclusiva do professor.'},403);
    if(body.review_confirmed!==true)return json({error:'Confirme a revisão antes de salvar.'},400);
    if(job.correction_scope&&job.correction_scope!=='complete'){
     const review={...partial.normalize(body.partial_review,{stage:job.correction_scope,theme:job.theme_snapshot,text:job.input_snapshot,context:job.context_snapshot||{}}),reviewed_by_teacher:true,review_audit:{policy_version:partial.version,confirmed:true}};
     return json({job:visible(checked(await admin.rpc('review_live_job',{p_actor:actor,p_job:job.id,p_review:review})))});
    }
    const scores:any={},competencies:any={};
    for(const code of ['C1','C2','C3','C4','C5']){
     const value=body.scores?.[code];if(!Number.isInteger(value)||![0,40,80,120,160,200].includes(value))return json({error:'Confira a nota de '+code+'.'},400);
     scores[code]=value;competencies[code]={...job.result.competencies[code],score:value};
    }
    const evidence=reviewedEvidence(job.result,{...body,scores});
    if(evidence.review_audit.c1_reassessment?.diagnostic)competencies.C1.diagnostic=evidence.review_audit.c1_reassessment.diagnostic;
