export function listSearch(value:any){return String(value||'').normalize('NFC').replace(/[^\p{L}\p{N}\s-]/gu,' ').trim().replace(/\s+/g,' ').slice(0,100);}
export function jobSummary(essay:any,jobs:any[]){
