 const grouped=new Map<string,any[]>();for(const j of jobs){if(!grouped.has(j.essay_id))grouped.set(j.essay_id,[]);grouped.get(j.essay_id)!.push(j);}
 return essays.map(e=>({...e,summary:jobSummary(e,grouped.get(e.id)||[])}));
